// Generated by OrchestKit Claude Plugin
// Created: 2026-09-06
//
// Pins the tool-call XML sanitization in src/workflows/write-sections.js.
//
// A live /write run shipped `</invoke>` into the finished DOCX in five
// places across four sections, and `</text>` in others -- a subagent's own
// tool-call formatting leaking into the text it reports as its content.
// Section-writer output was not sanitized for tool-call fragments before it
// became article text. This test drives the whole workflow script (the same
// vm-wrapped technique as test_write_sections_audit_error.cjs) with a mock
// agent() that deliberately returns text containing tool-call XML, and
// asserts none of it survives into drafted paragraphs, rewrites, the
// synthesis pass, or the abstract.

const fs = require('fs');
const path = require('path');
const assert = require('assert');
const vm = require('vm');

const SRC_PATH = path.join(__dirname, '..', 'src', 'workflows', 'write-sections.js');
const SRC = fs.readFileSync(SRC_PATH, 'utf8').replace('export const meta', 'const meta');

function buildRunner() {
  const script = new vm.Script(
    '(async function __run(agent, pipeline, phase, log, args) {\n' + SRC + '\n});',
    { filename: SRC_PATH }
  );
  return script.runInThisContext();
}

async function pipelineMock(items, ...stages) {
  const results = [];
  for (let i = 0; i < items.length; i += 1) {
    let value = items[i];
    for (const stage of stages) {
      value = await stage(value, items[i], i);
    }
    results.push(value);
  }
  return results;
}

const DIRTY = 'Real prose.</invoke>\n<parameter name="x">leaked</parameter> more prose.</text>';
const CLEAN_FRAGMENT = 'invoke'; // must not appear as a stray tag once sanitized

async function run(args, agentImpl) {
  const runner = buildRunner();
  const agent = async (prompt, opts) => agentImpl(prompt, opts || {});
  const result = await runner(agent, pipelineMock, () => {}, () => {}, args);
  return result;
}

function assertNoXml(text, where) {
  assert.ok(typeof text === 'string', where + ' must be a string');
  assert.ok(!/<\/?(?:antml:)?(?:invoke|parameter|function_calls|text)\b[^>]*>/.test(text), where + ' still contains tool-call XML: ' + JSON.stringify(text));
}

(async () => {
  const thresholds = {
    rewriteCycles: { max: 3 },
    writerUnit: { targetWords: 300, minWords: 200, maxWords: 400 },
  };
  const outline = { units: [{ id: 'u1', title: 'Unit One', claim: 'c1', evidence: ['e1'] }] };

  let rewriteCount = 0;
  let rewriteSpawns = 0;
  const result = await run({ outline: outline, thresholds: thresholds }, (prompt, opts) => {
    const label = opts.label || '';
    if (label.indexOf('draft:') === 0) {
      return { unitId: 'u1', paragraphs: [{ paragraphIndex: 1, text: DIRTY }] };
    }
    if (label.indexOf('audit:') === 0) {
      // FAIL once so the rewrite path (also sanitized) gets exercised, then PASS.
      rewriteCount += 1;
      return rewriteCount === 1
        ? { results: [{ paragraphIndex: 1, verdict: 'FAIL', feedback: DIRTY }] }
        : { results: [{ paragraphIndex: 1, verdict: 'PASS', feedback: 'clean' }] };
    }
    if (label.indexOf('rewrite:') === 0) {
      rewriteSpawns += 1;
      return { paragraphs: [{ paragraphIndex: 1, text: DIRTY }] };
    }
    if (label === 'synthesize') return DIRTY;
    if (label === 'abstract') return { abstract: DIRTY };
    if (label === 'scorecard') return { dimensions: [{ id: 'structure', score: 5 }], total: 30 };
    return null;
  });

  assert.strictEqual(rewriteSpawns, 1, 'the rewrite path must actually be exercised so its sanitization is covered');
  const paragraph = result.sections[0].paragraphs[0];
  assert.strictEqual(paragraph.outcome, 'PASS');
  assert.strictEqual(paragraph.attempts, 2);
  assertNoXml(paragraph.text, 'drafted/rewritten paragraph text');
  assert.ok(paragraph.text.indexOf(CLEAN_FRAGMENT) === -1, 'the word "invoke" itself should not remain either, since it only ever appeared inside the stripped tag');
  assertNoXml(typeof result.synthesis === 'string' ? result.synthesis : (result.synthesis && result.synthesis.revisedDraft) || '', 'synthesis result');
  assertNoXml(result.abstract || '', 'abstract');

  console.log('test_write_sections_sanitize: assertions OK');
})().catch((err) => {
  console.error(err);
  process.exit(1);
});
